import confetti from 'canvas-confetti';

/**
 * Creates a celebratory confetti animation with multiple bursts of varying patterns.
 * Each burst has different characteristics for spread, velocity, and decay.
 */
const throwConfetti = () => {
	fire( 0.25, {
		spread: 26,
		startVelocity: 55,
	} );

	fire( 0.2, {
		spread: 60,
	} );

	fire( 0.35, {
		spread: 100,
		decay: 0.91,
		scalar: 0.8
	} );

	fire( 0.1, {
		spread: 120,
		startVelocity: 25,
		decay: 0.92,
		scalar: 1.2
	} );

	fire( 0.1, {
		spread: 120,
		startVelocity: 45,
	} );
}

/**
 * Fires a single burst of confetti with specified parameters.
 *
 * @param {Number} particleRatio - Ratio to determine number of particles (multiplied by base count of 200)
 * @param {Object} opts - Configuration options for the confetti burst
 * @param {Number} [opts.spread] - Angular spread of the particle burst in degrees
 * @param {Number} [opts.startVelocity] - Initial velocity of particles
 * @param {Number} [opts.decay] - Rate at which particles slow down (0-1)
 * @param {Number} [opts.scalar] - Scale factor for particle size
 */
const fire = ( particleRatio, opts ) => {
	const count = 200;
	const defaults = {
		origin: { y: 0.7 }
	};

	confetti( {
		...defaults,
		...opts,
		particleCount: Math.floor( count * particleRatio )
	} );
}

export default throwConfetti;
