/**
 * Type guard that checks if a variable is defined (i.e., not `undefined` and not `null`).
 * If it returns true, TypeScript narrows the variable's type within the calling scope to exclude null and undefined.
 *
 * @template T - The potential type of the variable (which might include null or undefined).
 * @param {T} variable - The variable being evaluated. Can be of any type.
 * @return {boolean} `true` if the variable is neither `undefined` nor `null`, acting as a type predicate.
 * Otherwise, returns `false`.
 * @example
 * let value: string | undefined | null = Math.random() > 0.5 ? "hello" : undefined;
 *
 * if (isDefined(value)) {
 * // TypeScript knows `value` is 'string' inside this block
 * console.log(value.toUpperCase());
 * } else {
 * // TypeScript knows `value` is 'undefined' or 'null' here
 * console.log("Value is not defined.");
 * }
 */
const isDefined = (variable) => {
    // Check if the variable is neither undefined nor null.
    // NonNullable<T> is a built-in utility type that removes undefined and null from T.
    return typeof variable !== 'undefined' && variable !== null;
};
export default isDefined;
