/**
 * Formats a duration into a human-readable string with optional short format.
 *
 * @param {String} unit - The unit of time. Must be one of: 'seconds', 'minutes', 'hours', 'days', 'weeks', 'months', 'years'
 * @param {number} number - The quantity of the time unit
 * @param {Boolean} [short=false] - If true, returns abbreviated format (e.g. "5 min" instead of "5 minutes").
 *                                 Uses Microsoft Writing Style Guide abbreviations:
 *                                 sec, min, h, d, wk, mo, yr
 * @throws {Error} If invalid unit is provided
 * @return {string} Formatted string like "5 minutes" or "1 hour" (or "5 min"/"1 h" if short=true)
 * @example
 * getFormattedDuration('minutes', 5) // Returns "5 minutes"
 * getFormattedDuration('hours', 1, true) // Returns "1 h"
 */
const getFormattedDuration = ( unit, number, short = false ) => {
	switch ( unit ) {
		case 'seconds':
			// If the short format is requested, return the short format
			if ( short ) {
				return _uo.utility.sprintf(
					/* translators: 1. A number */
					_uo.utility.escHTML( wp.i18n.__( '%1$s sec', 'uncanny-automator' ) ),
					number
				);
			}

			return _uo.utility.sprintf(
				/* translators: 1. A number */
				_uo.utility.escHTML( wp.i18n._n( '%1$s second', '%1$s seconds', number, 'uncanny-automator' ) ),
				number
			);

		case 'minutes':
			// If the short format is requested, return the short format
			if ( short ) {
				return _uo.utility.sprintf(
					/* translators: 1. A number */
					_uo.utility.escHTML( wp.i18n.__( '%1$s min', 'uncanny-automator' ) ),
					number
				);
			}

			return _uo.utility.sprintf(
				/* translators: 1. A number */
				_uo.utility.escHTML( wp.i18n._n( '%1$s minute', '%1$s minutes', number, 'uncanny-automator' ) ),
				number
			);

		case 'hours':
			// If the short format is requested, return the short format
			if ( short ) {
				return _uo.utility.sprintf(
					/* translators: 1. A number */
					_uo.utility.escHTML( wp.i18n.__( '%1$s h', 'uncanny-automator' ) ),
					number
				);
			}

			return _uo.utility.sprintf(
				/* translators: 1. A number */
				_uo.utility.escHTML( wp.i18n._n( '%1$s hour', '%1$s hours', number, 'uncanny-automator' ) ),
				number
			);

		case 'days':
			// If the short format is requested, return the short format
			if ( short ) {
				return _uo.utility.sprintf(
					/* translators: 1. A number */
					_uo.utility.escHTML( wp.i18n.__( '%1$s d', 'uncanny-automator' ) ),
					number
				);
			}

			return _uo.utility.sprintf(
				/* translators: 1. A number */
				_uo.utility.escHTML( wp.i18n._n( '%1$s day', '%1$s days', number, 'uncanny-automator' ) ),
				number
			);

		case 'weeks':
			// If the short format is requested, return the short format
			if ( short ) {
				return _uo.utility.sprintf(
					/* translators: 1. A number */
					_uo.utility.escHTML( wp.i18n.__( '%1$s wk', 'uncanny-automator' ) ),
					number
				);
			}

			return _uo.utility.sprintf(
				/* translators: 1. A number */
				_uo.utility.escHTML( wp.i18n._n( '%1$s week', '%1$s weeks', number, 'uncanny-automator' ) ),
				number
			);

		case 'months':
			// If the short format is requested, return the short format
			if ( short ) {
				return _uo.utility.sprintf(
					/* translators: 1. A number */
					_uo.utility.escHTML( wp.i18n.__( '%1$s mo', 'uncanny-automator' ) ),
					number
				);
			}

			return _uo.utility.sprintf(
				/* translators: 1. A number */
				_uo.utility.escHTML( wp.i18n._n( '%1$s month', '%1$s months', number, 'uncanny-automator' ) ),
				number
			);

		case 'years':
			// If the short format is requested, return the short format
			if ( short ) {
				return _uo.utility.sprintf(
					/* translators: 1. A number */
					_uo.utility.escHTML( wp.i18n.__( '%1$s yr', 'uncanny-automator' ) ),
					number
				);
			}

			return _uo.utility.sprintf(
				/* translators: 1. A number */
				_uo.utility.escHTML( wp.i18n._n( '%1$s year', '%1$s years', number, 'uncanny-automator' ) ),
				number
			);

		default:
			throw new Error( `Invalid delayUnit: ${ unit }` );
	}
};

export default getFormattedDuration;