// Import dependencies
import { isEmpty, escHTML } from '@core/utilities';

// Import dayjs and the plugins to get the relative time and translate the strings
import dayjs from 'dayjs';
import relativeTime from 'dayjs/plugin/relativeTime';
import updateLocale from 'dayjs/plugin/updateLocale';

dayjs.extend( updateLocale );
dayjs.extend( relativeTime );

dayjs.updateLocale( 'en', {
	relativeTime: {
		/* translators: 1. A relative time in the future, like "in 5 seconds" or "in 1 year" */
		future: escHTML( wp.i18n.__( 'in %s', 'uncanny-automator' ) ),
		/* translators: 1. A relative time in the past, like "5 seconds ago" or "1 year ago" */
		past: escHTML( wp.i18n.__( '%s ago', 'uncanny-automator' ) ),
		m: escHTML( wp.i18n.__( 'a minute', 'uncanny-automator' ) ),
		/* translators: 1. Number of minutes */
		mm: escHTML( wp.i18n.__( '%d minutes', 'uncanny-automator' ) ),
		h: escHTML( wp.i18n.__( 'an hour', 'uncanny-automator' ) ),
		/* translators: 1. Number of hours */
		hh: escHTML( wp.i18n.__( '%d hours', 'uncanny-automator' ) ),
		d: escHTML( wp.i18n.__( 'a day', 'uncanny-automator' ) ),
		/* translators: 1. Number of days */
		dd: escHTML( wp.i18n.__( '%d days', 'uncanny-automator' ) ),
		M: escHTML( wp.i18n.__( 'a month', 'uncanny-automator' ) ),
		/* translators: 1. Number of months */
		MM: escHTML( wp.i18n.__( '%d months', 'uncanny-automator' ) ),
		y: escHTML( wp.i18n.__( 'a year', 'uncanny-automator' ) ),
		/* translators: 1. Number of years */
		yy: escHTML( wp.i18n.__( '%d years', 'uncanny-automator' ) ),
		s: number => number === 1
			? escHTML( wp.i18n.__( 'a second', 'uncanny-automator' ) )
			/* translators: 1. Number of seconds */
			: escHTML( wp.i18n.__( '%d seconds', 'uncanny-automator' ) ).replace( '%d', number )
	}
} );

/**
 * Get a relative time from the provided source.
 *
 * @param {"date"|"relative-seconds"} sourceType The type of the source. It can either be a date string or seconds relative from the current date.
 * @param {String|Number} source The source to get the relative time from. It can either be a date string or a number of seconds.
 * @return {String|undefined} The relative time from the source. Returns undefined if the sourceType or source is invalid.
 */
const getRelativeTime = ( sourceType, source ) => {
	// Check if the date is defined
	if ( isEmpty( source ) ) {
		throw new Error( `getRelativeTime: source can't be empty` );
	}

	let targetDate;

	switch ( sourceType ) {
		case 'date':
			targetDate = dayjs( source );
			break;

		case 'relative-seconds':
			targetDate = dayjs().add( source, 'second' );
			break;

		default:
			throw new Error( `getRelativeTime: Invalid sourceType. It must be either "date" or "relative-seconds"` );
	}

	// Check if it's a valid date
	if ( ! targetDate.isValid() ) {
		throw new Error( `getRelativeTime: Couldn't create a valid date` );
	}

	// Return relative date
	return targetDate.fromNow();
}

export default getRelativeTime;
