// Import dependencies
import { unsafeCSS, css, html, LitElement } from 'lit';
import { customElement } from 'lit/decorators.js';
import { repeat } from 'lit/directives/repeat.js';

// Banner content
import bannerContents from './banner-contents';

// Import style for web component
import styles from './web-component-style.scss';

// Import images
import logoHorizontal from './img/logo-horizontal.svg';

/**
 * Web component representing the banner of the upgrade page
 *
 * @augments LitElement
 */
@customElement( 'uap-page-upgrade-banner' ) // eslint-disable-line require-jsdoc
export class AutomatorUpgradeBanner extends LitElement {
	// Define style
	static styles = css`${ unsafeCSS( styles ) }`;

	/**
	 * Renders the component
	 *
	 * @return {TemplateResult|undefined} The template
	 */
	render() {
		return html`
			<div class="banner">
				${ this._templateBackground }
				${ this._templateContent }
			</div>
		`;
	}

	/**
	 * Returns the template for the content
	 *
	 * @return {TemplateResult|undefined} The template
	 */
	get _templateContent() {
		return html`
			<div class="banner-content">
				<div class="banner-content-logo">	
					<img src="${ logoHorizontal }"/>
				</div>

				<h1
					class="banner-content-title"
				>
					${ _uo.utility.escHTML( wp.i18n._x( "Get Automator's full potential with Pro", 'Upgrade', 'uncanny-automator' ) ) }
				</h1>

				<div class="banner-content-description">
					<uo-markdown 
						allowed-tags="strong"
						.content=${ _uo.utility.escHTML( wp.i18n._x( 'Get **unlimited** integrations, triggers, actions, and apps. Enjoy **premium support**, early **access to features**, and more powerful benefits!', 'Upgrade', 'uncanny-automator' ) ) }>
					</uo-markdown>
				</div>

				<div class="banner-content-cta">
					${ this._templateCTAButton }
				</div>
			</div>
		`;
	}

	/**
	 * Returns the template for the CTA
	 *
	 * @return {TemplateResult|undefined} The template
	 */
	get _templateCTAButton() {
		switch ( UncannyAutomatorBackend._site.automator.license_details.scenario_id ) {
			// Pro Elite, valid license
			case 'pro-installed-license-active-pro-elite':
				return html`
					<uo-button
						color="primary"
						href=${ UncannyAutomatorBackend._site.automator.links.external.url_upgrade_to_pro }
						disabled
					>
						${ _uo.utility.escHTML( wp.i18n._x( 'See plans', 'Upgrade', 'uncanny-automator' ) ) }
					</uo-button>

					<div class="banner-content-cta-disclaimer">
						🎉 ${ _uo.utility.escHTML( wp.i18n._x( "You're already on the best plan!", 'Upgrade', 'uncanny-automator' ) ) } 
					</div>
				`;

			default:
				// Check if there is a CTA
				if ( _uo.utility.isEmpty( UncannyAutomatorBackend._site.automator.license_details.cta ) ) {
					return;
				}

				return repeat(
					UncannyAutomatorBackend._site.automator.license_details.cta,
					( cta, index ) => index,
					cta => this._templateSummaryCTAButton( cta )
				);
		}
	}

	/**
	 * Returns the template that displays a call-to-action button
	 *
	 * @param {CTAButton} cta - The call-to-action button
	 * @return {TemplateResult} The template
	 */
	_templateSummaryCTAButton( cta ) {
		return html`
			<uo-button
				color="success"
				href=${ cta.url }
			>
				${ cta.icon ? html`<uo-icon id=${ cta.icon }></uo-icon>` : '' }
				${ cta.label }
			</uo-button>
		`;
	}

	/**
	 * Returns the template for the background
	 *
	 * @return {TemplateResult|undefined} The template
	 */
	get _templateBackground() {
		return html`
			<div class="banner-background">
				<div class="banner-background-items">
					${
						repeat(
							this.bannerItems,
							item => item.id,
							item => this.templateBackgroundItem( item )
						)
					}
				</div>
			</div>
		`;
	}

	/**
	 * Returns the template for the background item
	 *
	 * @param {Object} item The item
	 * @param {String} item.id The item ID
	 * @param {String} item.icon The item icon
	 * @param {String} item.title The item title
	 * @return {TemplateResult|undefined} The template
	 */
	templateBackgroundItem( item ) {
		return html`
			<div class="banner-background-item">
				<div class="banner-background-item-icon">
					<uo-icon 
						id=${ item.icon }
						icon-style="solid"
					></uo-icon>
				</div>

				${ item.title }
			</div>
		`;
	}

	/**
	 * Returns the banner items in random order
	 *
	 * @return {Array} The banner items in random order
	 */
	get bannerItems() {
		return bannerContents.items.sort( () => 0.5 - Math.random() );
	}

	/**
	 * Gets the current plan ID.
	 *
	 * @return {String} The current plan ID.
	 */
	get currentTierName() {
		return UncannyAutomatorBackend._site.automator.license_details.current_plan;
	}
}
