/**
 * Button <uo-button>
 *
 * Attributes:
 * disabled  Disables the button.
 * loading   Adds loading animation to the button. Disables the button.
 * color     Color of the button. "secondary", "danger".
 * size      Size of the button. "small", "extra-small".
 * href      The hyperlink of the button.
 * target    The target of the button.
 */

// Import dependencies
import { unsafeCSS, css, html, LitElement } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { ifDefined } from 'lit/directives/if-defined.js';
import { isEmpty } from '@core/utilities';
import { confirm } from '@core/utilities';

// Import style for web component
import styles from './web-component-style.scss';

// eslint-disable-next-line require-jsdoc
@customElement( 'uo-button' )
export class AutomatorButton extends LitElement {
	/**
	 * Define style
	 *
	 * @type {Object}
	 */
	static styles = css`${ unsafeCSS( styles ) }`;

	/**
	 * Focus shadow elements when elements in the light DOM are focused
	 *
	 * @type {Object}
	 */
	static shadowRootOptions = {
		...LitElement.shadowRootOptions,
		delegatesFocus: true
	}

	/**
	 * The color variant of the button.
	 * Possible values: "secondary", "danger", etc.
	 * @type {String}
	 */
	@property( { type: String } )
	accessor color;

	/**
	 * When true, renders a filled button style variant.
	 * @type {Boolean}
	 */
	@property( { type: Boolean, reflect: true } )
	accessor filled;

	/**
	 * The size variant of the button.
	 * Possible values: "small", "extra-small", etc.
	 * @type {String}
	 */
	@property( { type: String } )
	accessor size;

	/**
	 * URL the button will navigate to when clicked.
	 * @type {String}
	 */
	@property( { type: String } )
	accessor href;

	/**
	 * Target attribute for the navigation, e.g., "_blank" for a new tab.
	 * Only applies when href is set.
	 * @type {String}
	 */
	@property( { type: String } )
	accessor target;

	/**
	 * The type of button, e.g., "submit" for form submission.
	 * @type {String}
	 */
	@property( { type: String } )
	accessor type;

	/**
	 * Name attribute for the button, used when submitting forms.
	 * @type {String}
	 */
	@property( { type: String } )
	accessor name;

	/**
	 * Value attribute for the button, used when submitting forms.
	 * @type {String}
	 */
	@property( { type: String } )
	accessor value;

	/**
	 * Button's disabled state. When true, the button cannot be clicked.
	 * @type {Boolean}
	 */
	@property( { type: Boolean, reflect: true } )
	accessor disabled;

	/**
	 * Button's loading state. Shows loading animation and disables the button.
	 * @type {Boolean}
	 */
	@property( { type: Boolean, reflect: true } )
	accessor loading;

	/**
	 * When set to true, the button will forcibly use the target specified in the button element, even if it requests to open the link in the same tab for an external link.
	 * @type {Boolean}
	 */
	@property( { type: Boolean, attribute: 'unsafe-force-target' } )
	accessor unsafeForceTarget = false;

	/**
	 * When true, shows a confirmation dialog before executing the button's action.
	 * Only works for links and form submissions, not for custom event listeners.
	 * @type {Boolean}
	 */
	@property( { type: Boolean, attribute: 'needs-confirmation' } )
	accessor needsConfirmation = false;

	/**
	 * Heading text for the confirmation dialog.
	 * @type {String}
	 */
	@property( { type: String, attribute: 'confirmation-heading' } )
	accessor confirmationHeading;

	/**
	 * Content text for the confirmation dialog.
	 * @type {String}
	 */
	@property( { type: String, attribute: 'confirmation-content' } )
	accessor confirmationContent;

	/**
	 * Label for the confirm button in the confirmation dialog.
	 * @type {String}
	 */
	@property( { type: String, attribute: 'confirmation-button-label' } )
	accessor confirmationButtonLabel;

	// eslint-disable-next-line require-jsdoc
	render() {
		return html`
			<button
				size=${ ifDefined( this.size ) }
				color=${ ifDefined( this.color ) }
				type=${ ifDefined( this.type ) }

				?disabled=${ this.disabled || this.loading }
				?loading=${ this.loading }
				?filled=${ this.filled }

				tabindex="0"

				@click=${ event => this._handleClick( event ) }
			>
				<slot></slot> ${ this._templateSuffixIcon }
			</button>
		`;
	}

	/**
	 * Template suffix icon
	 *
	 * @return {String|undefined} Returns the template suffix icon or undefined if the link is not external
	 */
	get _templateSuffixIcon() {
		// Check if the link will open in a new tab
		if ( this._modifiedTarget() === '_blank' ) {
			return html`<uo-icon id="external-link" icon-style="solid"></uo-icon>`;
		}
	}

	/**
	 * Handles clicks made to the component
	 *
	 * @param {PointerEvent} event The event
	 * @return {undefined}
	 */
	async _handleClick( event ) {
		// Check if the user is trying to open the link in a new tab
		// Middle click (button 1) or Ctrl/Cmd + Click
		const isNewTab = event.button === 1 || event.metaKey || event.ctrlKey;

		// Check if it's disabled and prevent the event
		if ( this.disabled ) {
			event.preventDefault();
			event.stopPropagation();
		}

		// Ask the user to confirm the action first
		if ( this.needsConfirmation ) {
			try {
				await confirm( {
					heading: this.confirmationHeading,
					content: this.confirmationContent,
					confirmButtonLabel: this.confirmationButtonLabel
				} );
			} catch ( e ) {
				event.preventDefault();
				event.stopPropagation();

				// Stop here
				return;
			}
		}

		// Make sure the button is not disabled
		if ( ! this.disabled ) {
			// Check if it has a hyperlink defined
			if ( ! isEmpty( this.href ) ) {
				// Open the link
				this.openLink( isNewTab );
			}

			// Check if it has a type defined
			if ( ! isEmpty( this.type ) ) {
				// Check if the user wants to submit a form
				if ( this.type == 'submit' ) {
					// Submit the form
					this.submitForm();
				}
			}
		}
	}

	/**
	 * Opens a link. This assumes this.href is set because we check for it in _handleClick().
	 *
	 * @param {Boolean} isNewTab Whether the link should be opened in a new tab
	 * @return {undefined}
	 */
	openLink( isNewTab ) {
		// Get the target. If the user pressed the middle button or the Ctrl/Cmd key, force the link to open in a new tab
		// If it's an external link, we always open it in a new tab, unless the developer forced the target to a different value
		const target = this._modifiedTarget( isNewTab );

		// The user added a link, we have to send him there
		// Simulate link
		const anchor = document.createElement( 'a' );

		// Set hyperlink
		anchor.setAttribute( 'href', this.href );

		// Check if it has a target defined
		if ( ! isEmpty( target ) ) {
			// Add target
			anchor.setAttribute( 'target', target );
		}

		// Simulate click
		anchor.click();
	}

	/**
	 * Get the modified target
	 *
	 * @param {Boolean} [userRequestedNewTab=false] Whether the user requested to open the link in a new tab
	 * @return {String} The modified target
	 */
	_modifiedTarget( userRequestedNewTab = false ) {
		// If there is no href, set the target to _self
		if ( _uo.utility.isEmpty( this.href ) ) {
			return '_self';
		}

		// Before returning the target, check if the user is trying to force the target to a new tab
		if ( userRequestedNewTab ) {
			// Open on a new tab regardless of the target. The user request is more important than the developer's forced target.
			return '_blank';
		}

		// Check if the developer is trying to force the target
		if ( this.unsafeForceTarget ) {
			// Return the target
			return this.target || '_self';
		}

		// Check if it's an external link
		if ( _uo.utility.isExternalUrl( this.href ) ) {
			// Open on a new tab
			return '_blank';
		}

		// Fallback
		return this.target || '_self';
	}

	/**
	 * Submits a form. This assumes this.type is set to "submit" because we check for it in _handleClick().
	 *
	 * @return {undefined}
	 */
	submitForm() {
		// Get the form
		const $form = this.closest( 'form' );

		// Create a fake submit button
		const $submitButton = document.createElement( 'button' );
		$submitButton.setAttribute( 'type', 'submit' );

		// Check if it has a name and value defined
		if ( ! isEmpty( this.name ) && ! isEmpty( this.value ) ) {
			// Add name and value
			$submitButton.setAttribute( 'name', this.name );
			$submitButton.setAttribute( 'value', this.value );
		}

		// Add it to the form
		$form.appendChild( $submitButton );

		// Trigger a click
		$submitButton.click();

		// Remove the button
		$form.removeChild( $submitButton );
	}
}
