import isDefined from '../is-defined'; // Type guard version
/**
 * Checks if a variable is considered "empty".
 * - `null` or `undefined` are empty.
 * - The boolean `false` is empty.
 * - Empty strings (`''`) are empty.
 * - Empty arrays (`[]`) are empty.
 * - Objects with no own enumerable string properties (`{}`) are empty.
 * (Note: This includes instances like `new Date()`, `new RegExp()` which have `typeof 'object'` but often no enumerable keys via `Object.keys`).
 *
 * All other values (numbers including 0, boolean `true`, non-empty strings/arrays/objects, functions, Symbols, BigInts etc.) are NOT considered empty.
 *
 * @param {unknown} variable - The variable being evaluated. Can accept any type (`unknown`).
 * @return {boolean} `true` if the variable is considered empty according to the rules, `false` otherwise.
 *
 * @example
 * isEmpty(null);      // true
 * isEmpty(undefined); // true
 * isEmpty(false);     // true
 * isEmpty('');        // true
 * isEmpty([]);        // true
 * isEmpty({});        // true
 * isEmpty('hello');   // false
 * isEmpty([1]);       // false
 * isEmpty({ a: 1 });  // false
 * isEmpty(0);         // false
 * isEmpty(true);      // false
 */
const isEmpty = (variable) => {
    // 1. Check for null or undefined using the isDefined type guard
    if (!isDefined(variable)) {
        return true;
    }
    // variable is now NonNullable<unknown>
    // 2. Check for the boolean value false
    // Need strict equality check
    if (variable === false) {
        return true;
    }
    // 3. Check for empty string
    if (typeof variable === 'string' && variable.length === 0) {
        return true;
    }
    // 4. Check for empty array
    if (Array.isArray(variable) && variable.length === 0) {
        return true;
    }
    // 5. Check for object with no own enumerable string properties
    if (typeof variable === 'object' && Object.keys(variable).length === 0) {
        return true;
    }
    // 6. If none of the above conditions for emptiness were met, it's not empty.
    return false;
};
export default isEmpty;
