// Import dependencies
import { unsafeCSS, css, html, LitElement } from 'lit';
import { customElement, property, query } from 'lit/decorators.js';
import cytoscape from 'cytoscape';

// Import style for web component
import styles from './web-component-style.scss';

/**
 * The web component for the hub-spoke graph.
 * @type {CustomElement}
 */
@customElement( 'uo-hub-spoke-graph' ) // eslint-disable-line require-jsdoc
export class AutomatorHubSpokeGraph extends LitElement {
	/**
	 * Styles for the component, imported from SCSS file.
	 * @type {CSSResultGroup}
	 */
	static styles = css`${ unsafeCSS( styles ) }`;

	/**
	 * The graph element.
	 * @type {HTMLElement}
	 */
	@query( '.graph' ) accessor $graph;

	/**
	 * The items of the graph.
	 * @type {Array}
	 */
	@property( { type: Array } ) accessor items = [];

	/**
	 * The width of the nodes.
	 * @type {Number}
	 */
	@property( { type: Number, attribute: 'node-width' } ) accessor nodeWidth = 50;

	/**
	 * The spacing factor between nodes.
	 * @type {Number}
	 */
	@property( { type: Number, attribute: 'spacing-factor' } ) accessor spacingFactor = 1;

	/**
	 * Renders the component.
	 *
	 * @return {TemplateResult|undefined} The template
	 */
	render() {
		// Check if it has items
		if ( this.items.length === 0 ) {
			return;
		}

		return html`
			<div class="graph"></div>
		`;
	}

	/**
	 * Called when the element is first updated.
	 */
	async firstUpdated() {
		// Check if it has items
		if ( this.items.length === 0 ) {
			return;
		}

		// Wait for the component to finish rendering
		await this.updateComplete;

		// Create a promise that resolves when the container has actual dimensions
		const containerReady = new Promise( resolve => {
			const ro = new ResizeObserver( () => {
				if ( this.parentElement.clientWidth > 0 && this.parentElement.clientHeight > 0 ) {
					ro.disconnect();
					resolve();
				}
			} );
			ro.observe( this.parentElement );
		} );

		// Wait for container to have dimensions
		await containerReady;

		setTimeout( () => {
			// Create the Cytoscape instance.
			this.createCytoscape();

			// Disable dragging of the graph.
			this.disableDragging();

			// Fit the graph to the container.
			this.fitGraph();

			// Handle the click event on a node.
			this.handleNodeClick();

			// Add animations to the graph.
			this.addAnimations();
		}, 50 );
	}

	/**
	 * Creates the Cytoscape instance.
	 */
	createCytoscape() {
		// Initialize the Cytoscape instance.
		this.cy = cytoscape( {
			// A HTML DOM element in which the graph should be rendered.
			// The container is expected to be an empty div; the visualisation owns the div.
			container: this.$graph,

			// Whether zooming the graph is enabled, both by user events and programmatically.
			zoomingEnabled: false,

			// Whether panning the graph is enabled, both by user events and programmatically.
			panningEnabled: false,

			// Whether user events (e.g. mouse wheel, pinch-to-zoom) are allowed to zoom the graph. Programmatic changes to zoom are unaffected by this option.
			userZoomingEnabled: false,

			// Whether user events (e.g. dragging the graph background) are allowed to pan the graph. Programmatic changes to pan are unaffected by this option.
			userPanningEnabled: false,

			// Whether box selection (i.e. drag a box overlay around, and release it to select) is enabled. If enabled while panning is also enabled, the user must use a modifier key (shift, alt, control, or command) to use box selection.
			boxSelectionEnabled: false,

			// Whether nodes should be unselectified (immutable selection state) by default (if true, overrides individual element state).
			autounselectify: true,

			// The stylesheet used to style the graph. For convenience, this option can alternatively be specified as a promise that resolves to the stylesheet.
			style: this.graphStyles,

			// An array of elements specified as plain objects. For convenience, this option can alternatively be specified as a promise that resolves to the elements JSON.
			elements: this.elementsDefinition,

			// A plain object that specifies layout options. Which layout's documentation for the options it supports. If you want to specify your node positions yourself in your elements JSON, you can use the preset layout — by default it does not set any positions, leaving your nodes in their current positions (i.e. specified in `options.elements` at initialisation time).
			// Use a concentric layout with zero padding and a spacing factor so the graph fills the container as much as possible.
			layout: {
				// The concentric layout organises the nodes into concentric circles, based on the specified metric. The nodes with the highest metric values are placed in the innermost circle, and the metric values of the nodes descend for each outward circle. Each circle has nodes with metric values between a specified range, with the nodes within a circle sorted accordingly. This layout is useful for highlighting relative importance of the nodes, and its visual effect can be reinforced by creating a style mapper to the metric — e.g. nodes with larger metric values are darker in colour.
				name: 'concentric',

				// The amount of padding to add around the graph.
				padding: 0,

				// The spacing factor between nodes.
				spacingFactor: this.spacingFactor,

				// Returns numeric value for each node, placing higher nodes in levels towards the centre.
				// This makes the node in the center of the graph have a higher value than the others.
				concentric: n => ( n.data( 'center' ) ? 2 : 1 ),

				// A function that returns the width of a level.
				levelWidth: () => 1,
			}
		} );
	}

	/**
	 * Disables dragging of the graph.
	 * It is called when the graph is created.
	 */
	disableDragging() {
		this.cy.nodes().ungrabify();
	}

	/**
	 * Fits the graph to the container.
	 * It is called when the graph is created.
	 */
	fitGraph() {
		// Initial fit
		this.cy.fit( null, 0 );

		// Force center alignment
		this.cy.center();
	}

	/**
	 * Handles the click event on a node.
	 * It is called when the graph is created.
	 */
	handleNodeClick() {
		// Bind tap (click) events: clicking a node opens its associated link.
		this.cy.on( 'tap', 'node', event => {
			const node = event.target;
			const link = node.data( 'link' );

			if ( link ) {
				window.open( link, '_blank' );
			}
		} );
	}

	/**
	 * Adds animations to the graph.
	 * It is called when the graph is created and initializes the floating animation.
	 */
	addAnimations() {
		// Store initial positions of all nodes
		this.cy.nodes().forEach( node => {
			node.scratch( 'basePosition', { ...node.position() } );
		} );

		// Add gentle floating animation
		this.startFloatingAnimation();
	}

	/**
	 * Creates a gentle floating animation for all nodes.
	 * Each node follows a unique but repeating pattern using sine waves with different frequencies.
	 * The movement is bounded and will remain within the graph limits indefinitely.
	 */
	startFloatingAnimation() {
		/**
		 * Animates the nodes.
		 * It is called when the graph is created and initializes the floating animation.
		 */
		const animate = () => {
			this.cy.nodes().forEach( node => {
				const basePos = node.scratch( 'basePosition' );
				const time = Date.now() / 3000; // Base time factor
				const offset = 5; // Maximum pixel offset

				// Create unique but consistent frequencies for each node
				const nodeId = node.id().charCodeAt( 0 );
				const freq1 = 0.5 + ( nodeId % 5 ) * 0.1;  // Range: 0.5-0.9
				const freq2 = 0.3 + ( nodeId % 7 ) * 0.1;  // Range: 0.3-0.9
				const phase1 = ( nodeId % 6 ) * Math.PI / 3;  // Divide circle into 6 parts
				const phase2 = ( nodeId % 4 ) * Math.PI / 2;  // Divide circle into 4 parts

				// Combine two sine waves for more organic movement
				const newPos = {
					x: basePos.x + Math.sin( time * freq1 + phase1 ) * offset,
					y: basePos.y + Math.sin( time * freq2 + phase2 ) * offset
				};

				node.position( newPos );
			} );

			// Request next frame
			this.animationFrameId = requestAnimationFrame( animate );
		};

		animate();
	}

	/**
	 * Cleans up animations when the component is disconnected from the DOM.
	 * Cancels any ongoing animation frames to prevent memory leaks.
	 */
	disconnectedCallback() {
		super.disconnectedCallback();
		if ( this.animationFrameId ) {
			cancelAnimationFrame( this.animationFrameId );
		}
	}

	/**
	 * Gets the elements definition for the graph.
	 * @return {Object} The elements definition containing nodes and edges
	 * @property {Array} nodes - Array of node objects, each with data containing id, image, and center properties
	 * @property {Array} edges - Array of edge objects connecting outer nodes to center node
	 */
	get elementsDefinition() {
		// Build the nodes array from this.items.
		// Mark the first item as the center.
		const nodes = this.items.map( ( item, index ) => ( {
			data: { ...item, center: index === 0 }
		} ) );

		// Build the edges array: connect each outer node (nodes[1..n]) to the center.
		const centerNodeId = nodes[0].data.id;
		const edges = [];

		// Connect each outer node to the center node.
		nodes.slice( 1 ).forEach( node => {
			edges.push( { data: { source: centerNodeId, target: node.data.id } } );
		} );

		return { nodes, edges };
	}

	/**
	 * The styles for the graph.
	 * Defines the visual appearance of nodes and edges.
	 * @return {Array} Array of style objects for Cytoscape
	 */
	get graphStyles() {
		return [
			{
				selector: 'node',
				style: {
					height: `${ this.nodeWidth }px`,
					width: `${ this.nodeWidth }px`,
					'background-fit': 'contain',
					'background-position': 'center',
					'background-image': 'data(image)',
					'background-color': '#ffffff'
				}
			},
			{
				selector: 'edge',
				style: {
					'curve-style': 'bezier',
					width: '5px',
					'target-arrow-shape': 'none',
					'line-color': '#f5f7fb'
				}
			}
		];
	}
}
